$app->get('/api/admin/domains/{id}/mailboxes.csv',function($q,$r,$a)use($auth,$repo){$u=$auth->user($q,['domain_admin']);$d=$repo->adminDomain((int)$a['id'],$u);$out="address,quota_mb,used_mb,status\n";foreach($repo->rows('SELECT address,quota_mb,used_mb,status FROM mailboxes WHERE domain_id=? ORDER BY address',[$d['id']])as$x)$out.=self::csvRow([$x['address'],$x['quota_mb'],$x['used_mb'],$x['status']]);return Http::csv($r,$out,'mailboxes-'.$d['name'].'.csv');});
