$app->get('/api/mail/settings',function($q,$r)use($auth,$repo,$ok){$u=$auth->user($q,['mailbox_user']);$m=$repo->mailbox($u);return$ok($r,self::one($repo->db,'SELECT * FROM settings WHERE mailbox_id=?',[$m['id']]));});
$app->patch('/api/mail/settings',function($q,$r)use($auth,$repo,$db,$version,$email,$ok){$u=$auth->user($q,['mailbox_user']);$m=$repo->mailbox($u);$x=self::one($db,'SELECT * FROM settings WHERE mailbox_id=?',[$m['id']]);$d=Http::body($q);$version($d,$x);$density=(string)($d['display_density']??$x['display_density']);if(!in_array($density,['compact','comfortable'],true))throw new ApiException(422,'validation_error','Invalid display density.',['display_density'=>'compact or comfortable']);$fwd=(bool)($d['forwarding_enabled']??$x['forwarding_enabled']);$address=(string)($d['forwarding_address']??$x['forwarding_address']);if($fwd)$address=$email($address,'forwarding_address');$vac=(bool)($d['vacation_enabled']??$x['vacation_enabled']);$msg=(string)($d['vacation_message']??$x['vacation_message']);if($vac&&trim($msg)==='')throw new ApiException(422,'validation_error','Vacation message required.',['vacation_message'=>'required when enabled']);$db->prepare('UPDATE settings SET signature=?,vacation_enabled=?,vacation_message=?,forwarding_enabled=?,forwarding_address=?,display_density=?,version=version+1 WHERE mailbox_id=?')->execute([(string)($d['signature']??$x['signature']),(int)$vac,$msg,(int)$fwd,$address,$density,$m['id']]);return$ok($r,self::one($db,'SELECT * FROM settings WHERE mailbox_id=?',[$m['id']]));});
}private static function one(PDO$db,string$sql,array$args):array{$s=$db->prepare($sql);$s->execute($args);$r=$s->fetch();if(!$r)throw new ApiException(404,'not_found','Resource not found.');return$r;}private static function scalar(PDO$db,string$sql,array$args):mixed{$s=$db->prepare($sql);$s->execute($args);return$s->fetchColumn();}private static function csvRow(array$v):string{$h=fopen('php://temp','r+');fputcsv($h,$v,',','"','\\');rewind($h);$line=(string)stream_get_contents($h);fclose($h);return$line;}}
